// entry guard: compares with the item's usual entries (median of previous records of the same kind)
function guard(inp){if(!inp)return;const key=inp.dataset.guard,sel=document.querySelector(`[data-guard-item="${key}"]`),msg=document.querySelector(`[data-guard-msg="${key}"]`),i=st.M.ing.get(sel?.value),v=N(inp.value);if(!msg||!i)return;
 const hist=(inp.dataset.kind==='waste'?st.M.wastes:st.M.receipts).filter(x=>x.item===i.id&&!(inp.dataset.kind==='waste'&&x.qty>=20&&/^(kg|l)$/.test(UK(i.recipeUnit)))).map(x=>x.qty).sort((a,b)=>a-b),med=hist.length?hist[Math.floor(hist.length/2)]:null,u=UK(i.recipeUnit);
 let warn='';if(v>0&&(u==='kg'||u==='l')&&v>=20&&inp.dataset.kind==='waste')warn=`«${fa.format(v)} ${i.recipeUnit}» زیاد است؛ اگر منظور گرم است ${fa2.format(v/1000)} وارد کنید.`;else if(v>0&&med&&v>=10*med)warn=`معمولاً حدود ${fa2.format(med)} ${i.recipeUnit} ثبت می‌شود؛ مطمئنید؟`;
 msg.innerHTML=warn?`<span class="neg">⚠ ${warn}</span>`:v>0?`<span class="pos">✓ واحد: ${esc(i.recipeUnit)}</span>`:''}

