 bevDaily(el,days,P);
 RT.chart('chBevDay',t=>({...RT.base(t),legend:{top:0,textStyle:{color:t.text2,fontFamily:t.font}},grid:{left:8,right:8,top:36,bottom:4,containLabel:true},xAxis:{type:'category',data:days.map(d=>d.date.slice(5)),...RT.axis(t)},yAxis:{type:'value',...RT.axis(t)},series:[{name:'کسری روز',type:'bar',stack:'b',data:days.map(d=>d.short),itemStyle:{color:t.danger}},{name:'کاهش شب',type:'bar',stack:'b',data:days.map(d=>d.night),itemStyle:{color:t.palette[3]}}]}));
 RT.chart('chBevMonth',t=>({...RT.base(t),tooltip:{...RT.base(t).tooltip,valueFormatter:v=>RT.money(v)},xAxis:{type:'category',data:bevMonth.map(x=>x.label),...RT.axis(t)},yAxis:{type:'value',...RT.axis(t,{axisLabel:{color:t.text3,formatter:v=>RT.short(v)}})},series:[{type:'bar',data:bevMonth.map(x=>Math.round(x.v)),itemStyle:{color:p=>p.value<0?t.danger:t.success,borderRadius:[6,6,6,6]}}]}));
