 for(const [mid,qty] of P.menuSold){const m=st.M.menu.get(mid);if(!m||!(qty>0))continue;if(!withOil.has(mid)&&!E.FRIED_RE.test(S(m.name)))continue;const line=A(st.M.pr.recipes).find(x=>x.menuItemId===mid&&x.ingredientId===oil?.id);out.push({id:mid,name:m.name,code:m.code,qty,current:line?N(line.quantity):null,weight:W[mid]??E.friedWeight(m.name)})}
