function countsView(el){const inv=st.M.inv,groups=new Map;for(const s of A(inv.stocktakes)){const k=`${E.D(s.date)}|${s.isOpeningBaseline?'O':'W'}`;const g=groups.get(k)||{date:E.D(s.date),opening:!!s.isOpeningBaseline,list:[]};g.list.push(s);groups.set(k,g)}
 const salesAfter=s=>{const t=[S(s.approvedAt||s.createdAt),S(s.varianceCheckedAt),S(s.varianceRecalculatedAt)].sort().pop();return A(inv.salesPeriods).some(sp=>sp.status!=='void'&&S(sp.updatedAt||sp.createdAt)>t&&E.D(sp.from||sp.date)<=E.D(s.date))};
 el.innerHTML=card('انبارگردانی‌ها','هر شمارش با وضعیت، پوشش و مغایرت ذخیره‌شده؛ «کهنه» یعنی بعد از شمارش (یا آخرین بازمحاسبه) فروش دوره‌اش ثبت شده؛ ثبت‌های پنل جدید شمارش‌های بعدی را خودکار بازمحاسبه می‌کنند و «بازمحاسبهٔ مغایرت‌ها» بقیه را',table(['تاریخ','نوع','زمان',{l:'شمارش‌ها',num:1},{l:'اقلام',num:1},'وضعیت',{l:'مغایرت ذخیره‌شده',num:1},'اعتبار',''],[...groups.values()].sort((a,b)=>b.date.localeCompare(a.date)).map(g=>{const lines=g.list.reduce((a,s)=>a+A(s.lines).length,0),stat={};g.list.forEach(s=>stat[s.status]=(stat[s.status]||0)+1);const saved=g.list.filter(s=>s.status!=='void').reduce((a,s)=>a+A(s.lines).reduce((b,l)=>b+N(l.varianceValueToman),0),0),stale=!g.opening&&g.list.some(s=>s.status!=='void'&&salesAfter(s)),b=g.list[0].baselineBoundary||(g.opening?'START':'END');
  return `<tr class="ic-click" data-act="count" data-v="${esc(g.date+'|'+(g.opening?'O':'W'))}"><td>${esc(g.date)}</td><td>${g.opening?'شمارش افتتاحیه':'شمارش کل'}</td><td>${b==='END'?'پایان روز':'ابتدای روز'}</td><td class="num">${q(g.list.length,0)}</td><td class="num">${q(lines,0)}</td><td>${Object.entries(stat).map(([k,v])=>`<span class="badge badge-${k==='approved'?'success':k==='void'?'neutral':'warning'}">${{approved:'تأییدشده',submitted:'منتظر تأیید',void:'باطل'}[k]||k} ${q(v,0)}</span>`).join(' ')}</td><td class="num ${sign(saved)}">${g.opening?'—':T(saved)}</td><td>${stale?'<span class="badge badge-danger">کهنه — دوباره محاسبه شود</span>':'<span class="badge badge-success">به‌روز</span>'}</td><td><i data-lucide="chevron-left"></i></td></tr>`})))}
function countModal(key){const [date,kind]=key.split('|'),list=A(st.M.inv.stocktakes).filter(s=>E.D(s.date)===date&&(kind==='O')===!!s.isOpeningBaseline&&s.status!=='void'),lines=list.flatMap(s=>A(s.lines).map(l=>({...l,status:s.status,by:s.countedByName||s.countedBy})));
 openModal(`شمارش ${date}`,table(['قلم','واحد',{l:'شمارش',num:1},{l:'مورد انتظار (ذخیره‌شده)',num:1},{l:'مصرف فروش (ذخیره‌شده)',num:1},{l:'مغایرت ذخیره‌شده',num:1},'وضعیت','شمارنده'],lines.sort((a,b)=>N(a.varianceValueToman)-N(b.varianceValueToman)).map(l=>`<tr><td>${esc(l.itemNameSnapshot||st.M.ing.get(l.ingredientId)?.name)}</td><td>${esc(l.unitSnapshot)}${l.unitSnapshot&&UK(l.unitSnapshot)!==UK(st.M.ing.get(l.ingredientId)?.recipeUnit)?' <span class="badge badge-warning">≠ '+esc(st.M.ing.get(l.ingredientId)?.recipeUnit)+'</span>':''}</td><td class="num">${q(N(l.actual),3)}</td><td class="num">${l.expected===undefined?'—':q(N(l.expected),2)}</td><td class="num">${q(N(l.salesConsumption),2)}</td><td class="num ${sign(N(l.varianceValueToman))}">${l.varianceValueToman===undefined?'—':T(N(l.varianceValueToman))}</td><td>${esc(l.status)}</td><td>${esc(l.by||'')}</td></tr>`)))}

